import json
from pathlib import Path
from lesson_authoring import entry as E
B=[['拉丁 timere → timidus','害怕 → 容易害怕、胆怯的'],['法语 timide／拉丁 timidus → 英语 timid','胆小；缺少信心']]
I=[['拉丁 timidus → 中世纪拉丁 intimidare、intimidatus','胆怯 → 使害怕'],['英语 intimidate','恐吓；使人感到压力、不敢行动']]
W=[
E('timid','/ˈtɪmɪd/','胆怯的；缺乏自信的；不够大胆的','想上前，却因害怕或没把握而缩回去。','经法语 timide 或直接来自拉丁 timidus，关联 timere 害怕。更远的来源不确定，不要硬拆成 time 时间。',B,'timid 可以说人怕生、不敢开口，也能说方案太保守、不敢迈大步。a timid smile 是带点怯意的笑，a timid response 则可能是在批评回应力度不够。这个词描述当下表现或倾向，不等于一个人永远没有勇气。','a timid child；a timid smile；a timid attempt；too timid to speak。','shy 常说社交中的害羞，timid 更广，可以是面对风险、动物或重大决定时胆怯。cautious 强调小心，未必缺乏勇气。',('The timid puppy stayed behind the chair until the room became quiet.','那只胆小的小狗一直躲在椅子后面，直到屋里安静下来。'),('The report criticized the company’s timid response to the problem.','报告批评公司应对这个问题时过于畏缩。'),sources=['https://www.etymonline.com/word/timid','https://www.oxfordlearnersdictionaries.com/definition/english/timid']),
E('timidly','/ˈtɪmɪdli/','胆怯地；怯生生地','动作已经做了，但声音、姿态仍带着不敢放开的样子。','英语 timid + -ly，把胆怯的形容词变成描述动作方式的副词。',B+[['英语 timid + -ly → timidly','带着胆怯或没把握的样子']],'ask timidly 是怯生生地问，step timidly into a room 是有些胆怯地走进去。它强调动作里流露出的不安，不只是声音轻或走得慢。人物描写用它，读者往往能看到试探、退缩的小动作。','ask timidly；smile timidly；step forward timidly。','quietly 只说安静，timidly 还说不够自信。一个人可以很轻声，却完全不胆怯。',('She raised her hand timidly and asked for another explanation.','她怯生生地举起手，请对方再解释一下。'),('The kitten stepped timidly out of the carrier.','小猫胆怯地从航空箱里迈了出来。'),sources=['https://en.wiktionary.org/wiki/timidly#English','https://www.oxfordlearnersdictionaries.com/definition/english/timidly']),
E('timidity','/tɪˈmɪdəti/','胆怯；缺乏自信；畏缩','把那种不敢往前走、不敢大胆做的状态，作为一件事来谈。','来自拉丁 timiditas，法语也有 timidité。现代可辨认 timid 与 -ity 的关系，但历史上名词有自身的借入来源。',[['拉丁 timere → timidus → timiditas','害怕 → 胆怯的 → 胆怯这种状态'],['英语 timidity','不敢行动或表达的胆怯、畏缩']],'overcome her timidity 是克服胆怯，the timidity of the proposal 是方案过于畏缩。后者不是说文件有情绪，而是说制定者没有拿出足够大胆的措施。这个词通常不可数，重点在状态或倾向。','overcome timidity；initial timidity；political timidity。','timidity 可以得到同情，也可以受到批评。谨慎考虑风险是 caution；因为害怕而不敢做，才更接近 timidity。',('Her initial timidity faded as she got to know the group.','随着对这个小组越来越熟悉，她最初的胆怯渐渐消失了。'),('The review criticized the timidity of the proposed reforms.','这篇评论批评了改革方案缺乏魄力。'),sources=['https://www.etymonline.com/word/timidity','https://en.wiktionary.org/wiki/timidity#English']),
E('timorous','/ˈtɪmərəs/','胆怯的；畏缩不前的','怕出错、怕惹麻烦，于是只敢轻轻试一下，不敢真正向前。','拉丁 timor 害怕 + -osus 充满，形成中世纪拉丁 timorosus，经古法语 temoros 进入英语。不是在英语 timid 后面直接加 -ous。',[['拉丁 timere → timor','害怕 → 恐惧、忧惧'],['中世纪拉丁 timorosus → 古法语 temoros → 英语 timorous','容易害怕、畏缩的']],'timorous 和 timid 意思接近，但更书面，常出现在小说、评论和批评里。a timorous objection 是连反对都不太敢放开说。读到它时抓住畏缩就够了，日常表达通常用 timid 更自然。','a timorous voice；a timorous response；timorous leaders。','timorous 是胆怯，temerity 却是冒失大胆，拼写相近也不能混为同义。它不是时间相关的词。',('A timorous voice from the back of the room asked whether the plan was safe.','屋后传来一个怯生生的声音，问这个计划是否安全。'),('The editorial called the response timorous and inadequate.','社论认为这一回应畏缩而且力度不足。'),sources=['https://www.etymonline.com/word/timorous','https://www.oxfordlearnersdictionaries.com/definition/english/timorous']),
E('intimidate','/ɪnˈtɪmɪdeɪt/','恐吓；使畏缩；让人感到压力','让对方心里发怵，觉得自己不敢说、不敢做或应付不了。','由中世纪拉丁 intimidare 的分词 intimidatus 借入，包含 in- 与 timidus 胆怯。这里的 in- 不是不，而是使人进入胆怯状态的构词部分。',I,'有人故意威胁你闭嘴，是 intimidate you。一个人资历很强、气场很大，也可能 intimidate you，让你不敢搭话，但他未必有意吓你。这个词的共同点是削弱你的信心，让你缩回去。','intimidate somebody；intimidate somebody into doing something；be intimidated by something。','threaten 常明确提出威胁；intimidate 也可以没有威胁话语，仅凭态度、地位或难度就让人发怵。不是让人不胆怯。',('They tried to intimidate him into withdrawing his complaint.','他们试图恐吓他，让他撤回投诉。'),('Do not let the size of the manual intimidate you; start with the first chapter.','别被这本手册的厚度吓住，先从第一章开始。'),sources=['https://www.etymonline.com/word/intimidate','https://www.oxfordlearnersdictionaries.com/definition/english/intimidate']),
E('intimidating','/ɪnˈtɪmɪdeɪtɪŋ/','令人畏缩的；让人有压力的','还没开始，你就觉得这件事太难、这个场面太强，自己有点招架不住。','英语 intimidate 的 -ing 形式用作形容词，描述让别人害怕或没信心的人、事、环境。',I+[['英语 intimidate → intimidating','使人畏缩 → 令人感到压力的']],'an intimidating interview 是让人压力很大的面试，an intimidating amount of paperwork 是多到让人发怵的文书工作。它不一定危险或恶意，常只是规模、难度或气势让人觉得自己不够强。','an intimidating task；an intimidating atmosphere；find something intimidating。','intimidating 说造成压力的一方；intimidated 说感到被吓住的一方。The task is intimidating, and I feel intimidated。',('Speaking to a large audience can be intimidating at first.','刚开始面对大批听众讲话，可能会让人发怵。'),('The software looks intimidating, but the basic controls are simple.','这个软件看起来挺唬人，但基本操作很简单。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/intimidating','https://en.wiktionary.org/wiki/intimidating#English']),
E('intimidation','/ɪnˌtɪmɪˈdeɪʃən/','恐吓；威吓','通过制造害怕，让别人不敢反对、不敢退出，或被迫照做。','英语 intimidate 的动作名词，可能参照法语 intimidation 形成。-ation 把使人害怕的行为整体当作名词来谈。',I+[['英语 intimidate → intimidation','使人害怕 → 恐吓、威吓这种行为']],'workplace intimidation 可以是用威胁、敌意或强势态度压人。它通常比普通的紧张更强调外来的压迫：不是我自己怯场，而是有人在让别人不敢自由表达或行动。重点是用害怕给对方施压，让人觉得没有自由选择的余地。','threats and intimidation；a campaign of intimidation；intimidation tactics。','timidity 是自身胆怯的状态；intimidation 是使人害怕的行为。二者不能因为都带害怕就混译。',('The employees reported repeated threats and intimidation.','员工报告称，他们多次遭到威胁和恐吓。'),('The school made it clear that intimidation had no place in the debate.','学校明确表示，辩论中不允许用威吓压制别人。'),sources=['https://www.etymonline.com/word/intimidation','https://www.oxfordlearnersdictionaries.com/definition/english/intimidation'])]
ROOT=dict(id='C1521',meaning='害怕；胆怯',core='TIM = FEAR',image='一个人因害怕往后缩，是 timid；有人或某件事让他往后缩，是 intimidate。',intro='拉丁 timere 表示害怕，timidus 表示胆怯。最实用的区别是：自己不敢，和让别人不敢。timid、timidity 属于前者，intimidate、intimidating、intimidation 描述后者及其作用。',forms='timidity 和 timorous 各有拉丁来源支线。intimidate 的 in- 不是否定，所以不是不害怕。英语 time、timing 与这一组不能按外形混在一起。',branches=[['自己胆怯','timid, timidly, timidity, timorous'],['让别人发怵','intimidate, intimidating, intimidation']],contrasts='胆怯不等于安静，威吓也不一定通过大声喊叫。看句子究竟在讲人的状态、动作方式，还是造成压力的来源。',practice='The timid newcomer found the formal meeting intimidating.\n\n那个胆怯的新成员觉得这场正式会议很有压力。',words=[x['word'] for x in W],exclude={})
if __name__=='__main__':
 for name,data in [('roots_tim',[ROOT]),('words_tim',W)]:Path('.cache/batch200/drafts/root/'+name+'.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
 print(len(W),sum(len(x['examples']) for x in W))
